import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-tenant-token'];
  if (!token) return res.status(401).json({ error: 'Missing tenant token' });
  // In production this would verify JWT signature
  try {
    const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString());
    req.tenantId = payload.tenant_id;
    req.userId = payload.sub;
    next();
  } catch (e) {
    res.status(401).json({ error: 'Invalid token' });
  }
}

// Search endpoint with dynamic filtering
app.get('/api/v2/assets/search', extractTenant, async (req, res) => {
  try {
    const { category, status, sort_by, direction } = req.query;

    // Base query with tenant isolation
    let query = `SELECT id, name, category, status, metadata, created_at 
                 FROM assets WHERE tenant_id = $1`;
    const params = [req.tenantId];
    let paramIdx = 2;

    // Apply filters
    if (category) {
      query += ` AND category = $${paramIdx}`;
      params.push(category);
      paramIdx++;
    }
    if (status) {
      query += ` AND status = $${paramIdx}`;
      params.push(status);
      paramIdx++;
    }

    // Dynamic ORDER BY - vulnerable to SQL injection
    if (sort_by) {
      const dir = direction === 'desc' ? 'DESC' : 'ASC';
      query += ` ORDER BY ${sort_by} ${dir}`;
    } else {
      query += ` ORDER BY created_at DESC`;
    }

    query += ` LIMIT 100`;

    const result = await pool.query(query, params);

    // Log access for audit
    await pool.query(
      'INSERT INTO audit_log (tenant_id, user_id, action, resource, timestamp) VALUES ($1, $2, $3, $4, NOW())',
      [req.tenantId, req.userId, 'SEARCH', '/api/v2/assets/search']
    );

    res.json({ data: result.rows, count: result.rows.length });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Bulk update endpoint
app.post('/api/v2/assets/bulk-update', extractTenant, async (req, res) => {
  const { asset_ids, updates } = req.body;
  if (!asset_ids || !Array.isArray(asset_ids)) {
    return res.status(400).json({ error: 'asset_ids must be an array' });
  }

  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const placeholders = asset_ids.map((_, i) => `$${i + 3}`).join(',');
    const updateQuery = `UPDATE assets SET status = $1, updated_at = NOW() 
                         WHERE tenant_id = $2 AND id IN (${placeholders})`;
    await client.query(updateQuery, [updates.status, req.tenantId, ...asset_ids]);
    await client.query('COMMIT');
    res.json({ updated: asset_ids.length });
  } catch (err) {
    await client.query('ROLLBACK');
    res.status(500).json({ error: 'Bulk update failed' });
  } finally {
    client.release();
  }
});

app.listen(process.env.PORT || 3000);
